import React from "react";
import { motion } from "framer-motion";
import { Sparkles, ArrowRight } from "lucide-react";

const CTAButton = () => (
  <motion.button
    whileHover={{ scale: 1.05 }}
    whileTap={{ scale: 0.95 }}
    className="group relative overflow-hidden rounded-xl bg-gradient-to-r from-blue-600 to-purple-600 px-8 py-4 font-semibold text-white shadow-lg transition-all duration-200 hover:shadow-xl active:scale-95"
  >
    <span className="relative z-10 flex items-center gap-2">
      Get Started <ArrowRight className="transition-transform duration-300 group-hover:translate-x-1" />
    </span>
    <motion.span
      className="absolute inset-0 -z-0 bg-gradient-to-r from-blue-700 to-purple-700 opacity-0"
      whileHover={{ opacity: 0.2 }}
      transition={{ duration: 0.3 }}
    />
  </motion.button>
);

const Hero = () => {
  return (
    <section className="relative flex min-h-screen items-center justify-center overflow-hidden bg-gray-950 px-6 text-white">
      {/* Background Elements */}
      <div className="absolute inset-0 z-0">
        <div className="absolute -top-40 -right-40 h-80 w-80 rounded-full bg-blue-500 opacity-20 blur-3xl"></div>
        <div className="absolute -bottom-40 -left-40 h-80 w-80 rounded-full bg-purple-500 opacity-20 blur-3xl"></div>
        <div className="absolute left-1/2 top-1/2 h-96 w-96 -translate-x-1/2 -translate-y-1/2 rounded-full border border-gray-700 bg-gradient-to-t from-gray-900 to-transparent opacity-30"></div>
      </div>

      {/* Hero Content */}
      <div className="relative z-10 mx-auto max-w-5xl text-center">
        <motion.div
          initial={{ opacity: 0, y: 20 }}
          animate={{ opacity: 1, y: 0 }}
          transition={{ duration: 0.6 }}
          className="mb-8"
        >
          <div className="mb-4 inline-flex items-center gap-2 rounded-full bg-white/10 px-6 py-2 text-sm font-medium text-blue-200 backdrop-blur-md">
            <Sparkles className="h-4 w-4" />
            Powered by Artificial Intelligence
          </div>
        </motion.div>

        <motion.h1
          initial={{ opacity: 0, y: 30 }}
          animate={{ opacity: 1, y: 0 }}
          transition={{ duration: 0.8, delay: 0.2 }}
          className="mb-6 bg-gradient-to-r from-white via-gray-200 to-gray-400 bg-clip-text text-4xl font-extrabold leading-tight tracking-tight text-transparent sm:text-5xl lg:text-6xl"
        >
          Transform Ideas into Reality with Nexus AI
        </motion.h1>

        <motion.p
          initial={{ opacity: 0, y: 30 }}
          animate={{ opacity: 1, y: 0 }}
          transition={{ duration: 0.8, delay: 0.4 }}
          className="mx-auto mb-12 max-w-3xl text-lg leading-relaxed text-gray-300"
        >
          Unlock the power of next-generation AI to generate content, analyze data, and automate workflows—all in one seamless platform.
        </motion.p>

        <motion.div
          initial={{ opacity: 0, y: 30 }}
          animate={{ opacity: 1, y: 0 }}
          transition={{ duration: 0.8, delay: 0.6 }}
        >
          <CTAButton />
        </motion.div>
      </div>

      {/* Subtle Grid Pattern */}
      <div
        className="pointer-events-none absolute inset-0 z-0 opacity-5"
        style={{
          backgroundImage: `
            linear-gradient(rgba(255, 255, 255, 0.1) 1px, transparent 1px),
            linear-gradient(90deg, rgba(255, 255, 255, 0.1) 1px, transparent 1px)
          `,
          backgroundSize: '50px 50px',
        }}
      ></div>
    </section>
  );
};

export default Hero;

import React from "react";
import { motion } from "framer-motion";
import { Twitter, Linkedin, Github } from "lucide-react";
import clsx from "clsx";
import tailwindMerge from "tailwind-merge";

// Define social media links and their respective icons
const socialLinks = [
  { name: "Twitter", icon: Twitter, url: "https://twitter.com/NexusAI" },
  { name: "LinkedIn", icon: Linkedin, url: "https://linkedin.com/company/NexusAI" },
  { name: "GitHub", icon: Github, url: "https://github.com/NexusAI" },
];

// Framer Motion variants for a subtle entrance animation for the footer itself
const footerVariants = {
  hidden: { opacity: 0, y: 50 },
  visible: {
    opacity: 1,
    y: 0,
    transition: {
      duration: 0.6,
      ease: "easeOut",
      when: "beforeChildren", // Animate children after the parent footer
      staggerChildren: 0.1, // Stagger children animations
    },
  },
};

// Framer Motion variants for child elements (copyright text, social icons)
const itemVariants = {
  hidden: { opacity: 0, y: 20 },
  visible: {
    opacity: 1,
    y: 0,
    transition: {
      duration: 0.4,
      ease: "easeOut",
    },
  },
};

const Footer = () => {
  return (
    <motion.footer
      className={clsx(
        "w-full bg-gradient-to-r from-gray-900 to-gray-950 text-gray-200 py-8 px-4 sm:px-6 lg:px-8",
        "glass card-shadow"
      )}
      initial="hidden"
      animate="visible"
      variants={footerVariants}
    >
      <div className={tailwindMerge(
        {
          "max-w-7xl mx-auto flex flex-col md:flex-row items-center justify-between":
            true,
          "px-4 sm:px-6 lg:px-8 py-8": true,
          "bg-white/10 backdrop-filter backdrop-blur-md border border-gray-700/10 rounded-md glass":
            true,
        }
      )}
      >
        {/* Copyright Information */}
        <motion.p
          className="text-sm font-light mb-4 md:mb-0 text-gray-400 dark:text-gray-600"
          variants={itemVariants}
        >
          &copy; {new Date().getFullYear()} Nexus AI. All rights reserved.
        </motion.p>

        {/* Social Media Links */}
        <div className="flex space-x-6">
          {socialLinks.map((link) => (
            <motion.a
              key={link.name}
              href={link.url}
              target="_blank"
              rel="noopener noreferrer"
              className={clsx(
                "text-gray-400 hover:text-blue-400 transition-colors duration-300 transform",
                "focus:outline-none focus:ring-2 focus:ring-blue-500 focus:ring-offset-2 focus:ring-offset-gray-900 rounded-md"
              )}
              variants={itemVariants}
              whileHover={{ scale: 1.15, y: -5, transition: { type: "spring", stiffness: 400, damping: 10 } }}
              aria-label={`Link to Nexus AI's ${link.name}`}
            >
              <link.icon size={24} strokeWidth={1.5} />
            </motion.a>
          ))}
        </div>
      </div>
    </motion.footer>
  );
};

export default Footer;

:root {
  --color-primary-light: #f0f4f8;
  --color-primary-dark: #0f172a;
  --color-text-light: #1e293b;
  --color-text-dark: #e2e8f0;
  --color-accent-blue: #3b82f6;
  --color-accent-purple: #8b5cf6;
  --color-border-glass: var(--tw-ring-color);
  --color-bg-glass: rgba(0, 0, 0, 0.05);
  --bg-base-100: #0f172a;
  --color-text-base: #fff;
  --ring-color: #3b82f6;
  --ring-offset: 2px;
  --shadow-card: 0 10px 30px rgba(0, 0, 0, 0.2), 0 0 0 1px rgba(255, 255, 255, 0.05) inset;
  --shadow-glass: 0 4px 30px rgba(0, 0, 0, 0.1);
}

body {
  background-color: var(--bg-base-100);
  color: var(--color-text-base);
  font-family:
    system-ui,
    -apple-system,
    BlinkMacSystemFont,
    'Segoe UI',
    Roboto,
    Oxygen,
    Ubuntu,
    Cantarell,
    'Open Sans',
    'Helvetica Neue',
    sans-serif;
  -webkit-font-smoothing: antialiased;
  -moz-osx-font-smoothing: grayscale;
  min-height: 100vh;
  display: flex;
  flex-direction: column;
}

#root {
  flex-grow: 1;
  display: flex;
  flex-direction: column;
}

.glass {
  background-color: var(--color-bg-glass);
  backdrop-filter: blur(10px);
  -webkit-backdrop-filter: blur(10px);
  border: 1px solid var(--ring-color);
  box-shadow: var(--shadow-glass);
  border-radius: 12px;
}

.card-shadow {
  box-shadow: var(--shadow-card);
}

/* Custom scrollbar styles */
::-webkit-scrollbar {
  width: 8px;
  height: 8px;
}

::-webkit-scrollbar-track {
  background: var(--bg-base-100);
}

::-webkit-scrollbar-thumb {
  background: var(--ring-color);
  border-radius: 4px;
}

::-webkit-scrollbar-thumb:hover {
  background: var(--accent-purple);
}

::selection {
  background: var(--ring-color);
  color: var(--color-text-base);
}

:focus-visible {
  @apply ring ring-offset ring-offset-base ring-color focus-visible:outline-none;
}


