    :root {
      --shadow-sm: 0 1px 3px 0 rgba(0, 0, 0, 0.1);
    }

    html {
      scroll-behavior: smooth;
    }

    body {
      font-family: 'Nunito Sans', -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, 'Helvetica Neue', Helvetica, Arial, ' sans-serif';
      margin: 0;
      padding: 0;
      font-size: 16px;
      font-weight: 400;
      line-height: 1.5;
    }
  `}
`;

export default GlobalStyles;
